    public static class हरवशरयबचचन
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "हारना तब आवश्यक हो जाता है, जब लड़ाई अपनों से हो, और जीतना तब आवश्यक हो जाता है, जब लड़ाई अपने आप से हो।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "लहरों से डर कर नौका पार नहीं होती, कोशिश करने वालों की कभी हार नहीं होती।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "मंजिल मिले ये तो मुकद्दर की बात है, हम कोशिश न करे ये तो गलत बात है।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "आज अपने ख़्वाब को मैं सच बनाना चाहता हु, दूर की इस कल्पना के पास जाना चाहता हूँ।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "मन का हो जाए तो अच्छा, न हो तो और भी अच्छा।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "तू न थकेंगा कभी, तू न थमेंगा कभी, तू न मुड़ेगा कभी, कर शपथ कर शपथ कर शपथ, अग्निपथ अग्निपथ, अग्निपथ।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "किसी ने बर्फ से पूछा की आप इतने ठंडे क्यों हो? बर्फ ने कहा मेरा अतीत भी पानी है, मेरा भविष्य भी पानी है फिर मैं घमड़ किस बात का रखू।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "गिरना भी अच्छा है, औकात का पता चल जाता है। बढ़ते है जब हाथ उठाने को अपनो का पता चलता है।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "रब ने नवाजा हमे जिंदगी देकर, हम शौहरत मांगते रह गए।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "क्या बात करे इस दुनिया की हर शख्स के अपने अफ़साने है जो सामने है उसे बुरा कहते है और जिसको कभी देखा नहीं उसे सभी खुदा कहते है।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "जब मुसीबत आये तो समझ जाना जनाब जिंदगी हमें कुछ नया सिखाने वाली है।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "जिंदगी में इतने व्यस्त हो जाओ की उदास होने का वक्त ही न मिले।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "मजबूरियां देर रात तक जागती है और जिम्मेदारियां आपको सुबह जल्दी उठा देती है।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "सोचा था घर बनाकर बैठूँगा सुकून से पर घर की जरूरत ने मुसाफिर बना डाला।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "संघर्ष इंसान को मजबूत बनाता है, फिर चाहे वो कितना ही कमजोर क्यों ना हो।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "आज अपने ख्वाब को मैं सच बनाना चाहता हूं, दूर की इस कल्पना के पास जाना चाहता हूं।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "जो लहरों से डरता है वह कभी भी नौका पार नहीं कर पाता है।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "सीख रहा हूँ अब मैं भी इंसानों को पढ़ने का हुनर, सुना है चेहरे पर किताबों से ज्यादा लिखा होता है।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "ये समंदर भी तेरी तरह खुदगर्ज निकला, जिंदा थे तो तैरने ने दिया और मर गए तो डूबने न दिया।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "कभी फूलों की तरह मत जीना जिस दिन खिलोगे बिखर जाओगे,जीना है तो पत्थर बन के जियो, किसी दिन तराशे गए तो खुदा बन जाओगे।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "जो बीत गयी सो बात गयी जीवन एक सितारा था। माना वह बेहद प्यारा था, वह डूब गया तो डूब गया, अंबर के आनन को देखो।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "बैठ जाता हूं, मिट्टी पर अक्सर क्योंकि मुझे मेरी औकात अच्छी लगती है। मैंने समंदर से सीखा है, जीने का सलीका, चुपचाप से बहना और मौज में रहना।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "मैं छुपाना जानता तो जग मुझे साधु समझता, शत्रु बन गया है छल रहित व्यवहार मेरा।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "प्यार किसी को करना, लेकिन कहकर उसे बताना क्या, अपने को अर्पण करना पर औरों को अपनाना क्या।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "मैं यादों का किस्सा खोलूं, तो कुछ दोस्त बहुत याद करते हैं।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "हो जाए न पथ में रात कहीं, मंजिल भी तो है दूर नहीं। यह सोच थका दिन का पंथी भी जल्दी जल्दी चलता है, दिन जल्दी जल्दी ढलता है।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "संघर्ष का मैदान छोड़ मत भागो तुम, कुछ किये बिना ही जय जयकार नहीं होती। कोशिश करने वालों की कभी हार नही होती।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "एक बरस में एक बार ही जलती होली की ज्वाला, एक बार ही लगती बाजी, जलती दीपों की माला। दुनिया वालों किंतु किसी दिन आ मंदिरालय में देखो,दिन को होली रात को दिवाली, रोज मनाती मधुशाला।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "जग भव सागर तरने को नाव बनाए, मैं भव मौजों में मस्त बहा करता हूं।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "मैं जग जीवन का भार लिए फिरता हूं, फिर भी जीवन में प्यार लिए फिरता हूं। कर दिया किसी ने झंकृत जिनको छूकर, मैं सांसों में दो तार लिए फिरता हूं।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "गुजरते वक्त के साथ एक दिन यूं ही गुजर जाऊंगा, करके कुछ आँखों को नम कुछ दिलों में यादे बन कर बस जाऊँगा।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "जो छूट गए फिर कहाँ मिले पर बोलो टूटे तारों पर, कब अम्बर शोक मनाता है, जो बीत गई सो बात गई।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "उतर नशा जब उसका जाता, आती है संध्या बाला, बड़ी पुरानी, बड़ी नशीली नित्य ढला जाती हाला। जीवन की संताप शोक सब इसको पीकर मिट जाते, सुरा-सुप्त होते मद-लोभी जागृत रहती मधुशाला।", Author = "हरिवंश राय बच्चन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/हरिवंश_राय_बच्चन", Text = "मैं जग-जीवन का भार लिए फिरता हूँ, फिर भी जीवन में प्यार लिए फिरता हूँ।", Author = "हरिवंश राय बच्चन" },
        };
    }
}